import{_ as a,c as e,o as t,a4 as o}from"./chunks/framework.iMXuyU9c.js";const p=JSON.parse('{"title":"台式机主板规格","description":"","frontmatter":{},"headers":[],"relativePath":"电子硬件/台式机主板规格.md","filePath":"电子硬件/台式机主板规格.md"}'),i={name:"电子硬件/台式机主板规格.md"},r=o(`<h1 id="台式机主板规格" tabindex="-1">台式机主板规格 <a class="header-anchor" href="#台式机主板规格" aria-label="Permalink to &quot;台式机主板规格&quot;">​</a></h1><pre><code>该文创建于 2024/11/27
文章参考 [主板尺寸解释](https://cn.windows-office.net/?p=10947)
</code></pre><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1><p>常用的主板尺寸,按照「从小到大」 的顺序排列,分为 ITX、M-ATX、ATX 和 E-ATX，尺寸的大小，也相关者扩展性能的不同</p><h2 id="itx" tabindex="-1">ITX <a class="header-anchor" href="#itx" aria-label="Permalink to &quot;ITX&quot;">​</a></h2><p>或叫Mini-ITX,常说的超小型机箱，适合组件超mini电脑。itx机箱有不同的结构设计，但共同特点就是尺寸小乔，而且一般都设置提手方便搬运。</p><h2 id="m-atx-micro-atx" tabindex="-1">M-ATX(Micro ATX) <a class="header-anchor" href="#m-atx-micro-atx" aria-label="Permalink to &quot;M-ATX(Micro ATX)&quot;">​</a></h2><h2 id="atx" tabindex="-1">ATX <a class="header-anchor" href="#atx" aria-label="Permalink to &quot;ATX&quot;">​</a></h2><p>“标准 ATX”主板。 ATX 代表“先进技术扩展”，早在 1995 年就已开发出来。如果您拥有或曾经拥有一台普通尺寸的 PC，那么它很可能拥有 ATX 主板。这使得 ATX 成为购买 PC 或主板时的“常规”选择。 <img src="https://windows-office.net/common-images/eatx-atx-micro-atx-mini-itx/Motherboard-sizes-explained-atx-motherboard-asus.jpg" alt="" loading="lazy"></p><h2 id="e-atx" tabindex="-1">E-ATX <a class="header-anchor" href="#e-atx" aria-label="Permalink to &quot;E-ATX&quot;">​</a></h2><p>扩展 ATX，它为 ATX 主板增加了更多的面积和组件，因此尺寸稍大。</p>`,11),n=[r];function c(s,h,d,l,_,m){return t(),e("div",null,n)}const x=a(i,[["render",c]]);export{p as __pageData,x as default};
